namespace OpenTPW;

/// <summary>
/// The guest walk's approximation register (docs/GUESTS.md, "Walking"; docs/reverse/WALK-plan.md §11, §13). Each entry is
/// tagged <c>[APPROX:WALK-NNN]</c> at its code site. The speed model is traced from the Mac binary; a guest's walk on the park's
/// cells is tp.exe's (GuestNavigation.Navigate: the route search 0x511420, the edge test 0x4d8750 and commit 0x510510, avoid_walls
/// 0x50e4a0 with its corner blocks, follow_path 0x50ed10 with the block stamps, the progress 0x50fd40 and the steering step 0x50f3b0
/// with its own arithmetic), checked against the original in the x86 oracle (docs/reverse/ORACLE.md X25); separation is the Mac's (BIN labels at the code sites).
/// Retired: WALK-002 (avoid_walls' corner blocks and the position's cell), WALK-004 (the whole-walk destinations of state 10, one route to the ride's back cell, and
/// state 18, one route to the gate's crossing cell) and WALK-009 (the progress measure and its resets).
/// </summary>
public static class WalkApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("WALK-003", "separation's neighbours are the guests outside rides and shops (not Using, HeldByGuard or Gone) of a cell followed by the staff on it (classes 4-8, as the staff sweep does with the guests); the original's query (tp.exe 0x5102f0, Mac 0x10087c, at most five neighbours) visits each cell's things in the order they were head-inserted when they entered it (0x50b6a0 via 0x4d91f0), keeps class-1 guests whatever their state, and also keeps the online avatar (class 18); the neighbour position (thing +4/+6 = navigation position >> 8, written by 0x4fa2a0) matches OpenTPW's (the per-turn rebuilt cell lists themselves are [EXT:guest-cell-lists])"),
		("WALK-005", "the edge test 0x4d8750 reads only the cell map: OpenTPW's cells hold no object or thing references, so an object standing on a target cell (0x5363f0, its type record's 0x53ad20 bits) never blocks, a type-9 target's ride thing (on its owner cell +0x10, type 3: 0x42a440, 0x4dd4e0 +0x118) never decides a mask-2 step, and the underground link byte +0x22 (0x522770 with 0x81b4cc) is not kept; the types are the ones OpenTPW's tools write (path, queue and track cells; map init 0x536490's types 2, 5, 7 and 0x1e are not written, WALK-008)"),
		("WALK-006", "the walk into the ride's entrance cell (state 13's last walk, to the stand point), the arrival lanes' walks (WALK-008) and walks restored from saves made before the original walk keep OpenTPW's route walk: the route's cells (and the queue's next cells ahead and behind) are the walkable ones, avoid_walls has its edge branch only (with the probe's cell), refills come from the stored route, the stuck reroute prepends the current cell to the rest, progress compares raw remaining distances in the five-waypoint window, and the Mac's rounding FixMul/FixDiv apply; in the original every walk is the search and edge-test walk of Navigate, the step from the front queue cell into the ride's entrance cell (type 9) being open through that cell's +0x0C link, which OpenTPW's untyped ride cells do not carry (WALK-005)"),
		("WALK-007", "a route walk (WALK-006) restored from a save made before the original walk ends without a replan when a grid edit takes a cell or link of its route, and the queue recompute's own stamp of its back cell (tp.exe 0x4de1f0: the counter raised by 0x4d8c50 and written into the back cell's block by 0x4d8c60) is made after the queue tool's edits, but not yet after a path laid over a queue end or a cell clear of a queue cell (0x5346d0, 0x5367a0 call 0x4de1f0 on the owning ride, found through the cell's owner word +0x10, which OpenTPW's cells do not keep); the block stamps of every cell type change (0x4d8c60 from 0x5346d0, 0x5348d0, 0x538fc0) and the walk's comparison (0x50ed6c, a search in mode 1) are ported"),
		("WALK-008", "guests arriving on the arrival lanes, and guests whose map leaves a lane or stop cell untyped, walk off the path grid, with no wall force and every position committed; the original walks every guest through the route search 0x50f8e0, the commit 0x510510 and the edge test 0x4d8750 with the walk mask, the lane cells being type 0x1e (or path) from map init 0x536490, so only map-edge, entrance-building, water, ride and queue cells could push or refuse them; a leaving guest walks from the gate to the stop cells that way where the map types the lane (the original levels' map init does), and the arriving walk (states 0 to 5) is not ported: the original creates the guest at the bus stop in state 0 (0x4ff520: once 0x51a760 lets it, a world draw's bit 0 picks the side, two more draws the sub-cell bytes of that side's ticket booth cell 0x4d8610, one route request 0x4fa5f0 and state 2), state 2 (0x4ff730) steps with 0x4fa2a0, sets the purpose speed +0xc2 to 25 or 0 by the low two bits of the thing id (WALK-010) and ends in state 4, the booth, or in state 3 with the park closed, state 3 (0x4ff7f0) walks a paid guest to the entrance cell 0x4d8690 (0x4fa530, state 5) only while it heads its cell's thing list, and state 5 (0x4ffb20) walks it in, back to the booth (state 2) when the park is closed or the gate's script variable 1 is not 1, numbering the visitor on arrival (0x51aaf0 into +0x1d8, state 6); the lanes' cells are typed 0 in OpenTPW's Jungle and Hallow maps and the search crosses them in one segment, so the arrival would walk the cell map"),
		("WALK-010", "the needs phase that gates the toilet speed term compares the park turn with OpenTPW's guest id; the original compares the low two bits of the tick with the thing id (tp.exe 0x501676), taken from one pool of 10239 slots shared by every thing kind (allocator 0x516270, ids 1, 2, 3, ... on a fresh park, freed ids reused last-in first-out after the turn's deferred destroy), so the phase depends on the whole construction and destroy history")
	};
}
